const item = $input.first();
const headers = (item && item.json && item.json.headers) ? item.json.headers : {};
const token = headers['x-internal-token'] || headers['X-Internal-Token'];
const expected = $env.INTERNAL_SERVICE_KEY;
// Fail-closed: reject if env var is missing OR token doesn't match
if (!expected || token !== expected) {
  throw new Error('403 Forbidden: Invalid or missing X-Internal-Token header');
}
return $input.all();
